content.content:
200	                affects: Vec::new(),
201	            });
202	        }
203	    }
204	    if super::may_be_utility(type_name, consuming_file, ctx) {
205	        if let Some(alias) = super::substitute::synthesize_utility_alias(type_name_bare, type_args, consuming_file) {
206	            return resolve_type_alias_chain(&alias, consuming_file, mapping, ctx, state, depth);
207	        }
208	    }
209	
210	    // ── Step 0.6: React's `ComponentProps<typeof Button>` is `Button`'s props ─
211	    // `typeof` names a value, the component, so this finds the component instead of a type called `Button`, exactly as
212	    // the same reference does in an `extends` clause.
213	    if let Some(CollectedType::TypeOf(component)) = type_args.first() {
214	        let component_props =
215	            matches!(type_name_bare, "ComponentProps" | "ComponentPropsWithoutRef" | "ComponentPropsWithRef");
216	        if component_props && super::may_be_react_builtin(type_name, consuming_file, ctx) {
217	            return super::extends::component_props_of(component, consuming_file, mapping, ctx, state, depth);
218	        }
219	    }
220	
221	    // ── Step 1: TypeScript built-in utility types — silent no-op ─────────────
222	    // Not prop providers; suppress false "unresolvable" warnings.
223	    if ts_lib && super::is_ts_utility_type(type_name_bare) {
224	        return ResolvedChain::empty();
225	    }
226	
227	    // ── Step 2: Try the project's own source before a known-pattern shortcut ─
228	    // See `resolver::precedence` — the shared, single-source-of-truth order
229	    // `named.rs` already used correctly; this path used to reimplement the
230	    // sequence independently and check known patterns first, silently
231	    // replacing project-defined types (e.g. a project's own `interface
232	    // SxProps`) with the hardcoded library shortcut. Fixed: P0-1.
233	    let resolved_args: Vec<PropType> =
234	        type_args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
235	
236	    let (canonical_file, canonical_name, matched) =
237	        super::precedence::resolve_source_defined_or_known(type_name_bare, &resolved_args, consuming_file, ctx, state);
238	
239	    match matched {
240	        Some(super::precedence::SourceOrKnownMatch::TypeAlias { matched_key, alias }) => {
241	            // As for interfaces and for aliases in a prop position: parameters left unfilled by the call site are
242	            // placeholders in the body, not unresolvable types.
243	            if let Some(params) = ctx.named_types.lookup_type_alias_params(&canonical_file, &matched_key) {
244	                state.add_type_params(params.iter().skip(type_args.len()));
245	            }
246	            let alias = super::substitute::apply_generic_args(
247	                alias,
248	                (&canonical_file, &matched_key),
249	                type_args,
250	                consuming_file,
251	                ctx,
252	                &mut state.diagnostics,
253	            );
254	            if let CollectedTypeAlias::Passthrough { target: CollectedType::Object(fields), file_path } = &alias {
255	                if ctx.collapses(file_path, fields.len(), depth, state) {
256	                    let notable = fields
257	                        .iter()
258	                        .filter(|field| field.is_member() && is_notable(&field.name))
