260	                    return collapsed_source(
261	                        &canonical_name,
262	                        file_path,
263	                        fields.len(),
264	                        notable.collect(),
265	                        ctx,
266	                        state,
267	                        depth,
268	                    );
269	                }
270	            }
271	            let mut attempt = state.branch();
272	            let chain = resolve_type_alias_chain(&alias, consuming_file, mapping, ctx, &mut attempt, depth);
273	            return known_fallback(
274	                chain,
275	                attempt,
276	                type_name,
277	                &resolved_args,
278	                consuming_file,
279	                mapping,
280	                ctx,
281	                state,
282	                depth,
283	            );
284	        }
285	        Some(super::precedence::SourceOrKnownMatch::Interface(iface)) => {
286	            let mut attempt = state.branch();
287	            let chain = resolve_interface_chain(iface, type_args, consuming_file, mapping, ctx, &mut attempt, depth);
288	            return known_fallback(
289	                chain,
290	                attempt,
291	                type_name,
292	                &resolved_args,
293	                consuming_file,
294	                mapping,
295	                ctx,
296	                state,
297	                depth,
298	            );
299	        }
300	        Some(super::precedence::SourceOrKnownMatch::Known(result)) => {
301	            return known_chain(result, type_name, consuming_file, mapping, ctx, state, depth);
302	        }
303	        None => {}
304	    }
305	
306	    // ── Step 2.5: React builtin check (after source and known patterns) ──────
307	    // Terminal React types (ReactNode, Ref, FC, etc.) that survived both are not
308	    // prop providers — add to composes and stop.
309	    // A builtin name bound elsewhere reaches here only when that binding didn't resolve (a re-export of React's type, a
310	    // package not installed); React's meaning is then a reported guess.
311	    if react_types::is_react_builtin(type_name_bare, &ctx.extra_builtins) {
312	        if !ctx.extra_builtins.contains(type_name_bare) && !super::may_be_react_builtin(type_name, consuming_file, ctx)
313	        {
314	            state.diagnostics.push(super::builtin_fallback_diagnostic(type_name, consuming_file, ctx));
315	        }
316	        return ResolvedChain::empty_with_compose(type_name.to_owned());
317	    }
318	
319	    // HTML attribute interfaces (`InputHTMLAttributes`, ...) are terminal in curated mode, like the builtins above: the
320	    // element's notable attributes come from the inheritance layer, not from expanding the interface.
321	    if react_types::html_element_for(type_name_bare).is_some()
322	        || super::declared_by_react(type_name, &canonical_name, consuming_file, ctx)
323	    {
324	        // The element's attributes are still the props' (`Omit<HTMLAttributes<HTMLDivElement>, "title">`), so the
325	        // layer records them for the mode to list; `Omit` and `Pick` narrow it.
326	        let element = type_args
327	            .first()
328	            .and_then(react_types::html_element_from_collected)
329	            .or_else(|| react_types::html_element_for(type_name_bare));
330	        let mut chain = ResolvedChain::empty_with_compose(type_name.to_owned());
331	        if let Some(element) = element {
332	            chain.inheritance.push(InheritedLayer {
333	                type_name: type_name.to_owned(),
334	                file_name: resolve_react_types_file(consuming_file, ctx),
335	                omitted: vec![],
336	                html_element: Some(element.to_owned()),
337	                total_props: 0,
338	            });
339	        }
340	        return chain;
341	    }
342	
343	    // ── Step 6: Unresolvable ──────────────────────────────────────────────────
344	    // Import resolution may have redirected `type_name` to a different name/file
345	    // (re-exports, barrel files) — surface that resolved location when it differs,
346	    // since "Cannot resolve X in file A" is confusing if X actually lives in file B.
347	    let location_note = super::unresolved_location_note(type_name, consuming_file, &canonical_file, &canonical_name);
348	    state.diagnostics.push(Diagnostic {
349	        severity: DiagnosticSeverity::Warning,
350	        message: format!("Cannot resolve type '{}' in '{}'{}", type_name, consuming_file, location_note),
351	        file: Some(consuming_file.to_string()),
352	        line: None,
353	        column: None,
354	        help: Some(super::unresolved_type_help(
355	            type_name,
356	            consuming_file,
357	            ctx,
358	            "Type may be in an unresolvable cross-package location. Check that the package is installed.",
359	        )),
360	        code: DiagnosticCode::UnresolvableImport,
361	        affects: Vec::new(),
362	    });
363	    ResolvedChain::empty_with_compose(type_name.to_owned())
364	}
