371	/// A source recorded as a layer instead of expanded (collapse): `total` is how many props it declares; only `notable`
372	/// fields are resolved.
373	#[allow(clippy::too_many_arguments)]
374	fn collapsed_source(
375	    type_name: &str,
376	    file: &Utf8Path,
377	    total: usize,
378	    notable: Vec<(&str, CollectedType, bool, &str)>,
379	    ctx: &ResolutionContext,
380	    state: &mut ResolveState,
381	    depth: u8,
382	) -> ResolvedChain {
383	    let parent = PropParent { name: type_name.to_owned(), file_name: file.to_string() };
384	    let notable = notable
385	        .into_iter()
386	        .map(|(name, ty, required, description)| {
387	            let prop_type = resolve_collected_type(&ty, file, ctx, state, depth);
388	            let (parents, parent) = (vec![parent.clone()], Some(parent.clone()));
389	            let tags = Default::default();
390	            ctx.share(ParsedProp::new(
391	                name.to_owned(),
392	                prop_type,
393	                required,
394	                None,
395	                description.to_owned(),
396	                tags,
397	                parent,
398	                parents,
399	            ))
400	        })
401	        .collect();
402	    let layer = InheritedLayer {
403	        type_name: type_name.to_owned(),
404	        file_name: file.to_string(),
405	        omitted: vec![],
406	        html_element: None,
407	        total_props: u32::try_from(total).unwrap_or(u32::MAX),
408	    };
409	    ResolvedChain { inheritance: vec![layer], notable, ..ResolvedChain::empty() }
410	}
