705	fn interface_prop(
706	    iface: &CollectedInterface,
707	    args: &[CollectedType],
708	    key: &str,
709	    args_file: &Utf8Path,
710	    ctx: &ResolutionContext,
711	    depth: u8,
712	) -> Option<DeclaredProp> {
713	    let params = ctx
714	        .named_types
715	        .lookup_interface_type_params_for(iface)
716	        .or_else(|| ctx.react_types.as_deref()?.lookup_interface_type_params_for(iface));
717	    let defaults = ctx
718	        .named_types
719	        .lookup_interface_param_defaults_for(iface)
720	        .or_else(|| ctx.react_types.as_deref()?.lookup_interface_param_defaults_for(iface));
721	    let subst = match params {
722	        Some(params) if !params.is_empty() && (!args.is_empty() || defaults.is_some()) => {
723	            Some(bind_args(params, defaults, args, args_file, &iface.file_path, &mut Vec::new()))
724	        }
725	        _ => None,
726	    };
727	    // A member's type, or a parent's arguments (`extends StandardProperties<TLength>`), bound to `args`.
728	    let bind = |ty: &CollectedType| match &subst {
729	        Some(subst) => substitute_type(ty, subst),
730	        None => ty.clone(),
731	    };
732	    if let Some(prop) = iface.props.iter().find(|p| p.name == key) {
733	        return Some(DeclaredProp {
734	            ty: bind(&prop.collected_type),
735	            required: prop.required,
736	            description: prop.description.clone(),
737	            file: iface.file_path.clone(),
738	            declared_by: iface.name.to_string(),
739	        });
740	    }
741	    if depth > MAX_DEPTH {
742	        return None;
743	    }
744	    iface.extends.iter().find_map(|parent| {
745	        let (name, type_args) = match parent {
746	            ExtendsRef::SameFile { name, type_args } => (name, type_args),
747	            ExtendsRef::Imported { local_name, type_args, .. } => (local_name, type_args),
748	            // React's own interfaces name their parents by the spelling the extractor recognizes as React's
749	            // (`HTMLAttributes<T> extends AriaAttributes, DOMAttributes<T>`).
750	            ExtendsRef::Builtin { name, type_args, .. } => (name, type_args),
751	        };
752	        let (parent_file, parent_name) = canonical(name, &iface.file_path, ctx);
753	        let type_args: Vec<CollectedType> = type_args.iter().map(&bind).collect();
754	        match lookup_interface(ctx, parent_file.as_str(), &parent_name)
755	            .or_else(|| react_interface(ctx, &parent_file, &parent_name))
756	        {
757	            Some(parent) => interface_prop(parent, &type_args, key, &iface.file_path, ctx, depth + 1),
758	            // An interface may extend an alias (csstype's `StandardLonghandPropertiesFallback = Fallback<…>`).
759	            None => {
760	                let parent = CollectedType::Named { name: name.clone(), args: type_args };
761	                member(&parent, key, &iface.file_path, ctx, depth + 1).map(|(ty, file)| DeclaredProp {
762	                    ty,
763	                    required: false,
764	                    description: String::new(),
765	                    file,
766	                    declared_by: name.to_string(),
767	                })
768	            }
769	        }
770	    })
771	}
