773	/// A type alias's definition with `args` bound to its parameters, as one type.
774	pub(super) fn alias_body(
775	    name: &CompactString,
776	    args: &[CollectedType],
777	    file: &Utf8Path,
778	    ctx: &ResolutionContext,
779	) -> Option<Located> {
780	    let (alias_file, alias_name) = canonical(name, file, ctx);
781	    let (matched, alias) = lookup_type_alias(ctx, alias_file.as_str(), &alias_name)?;
782	    let defaults = ctx.named_types.lookup_type_param_defaults(&alias_file, &matched);
783	    let alias = match ctx.named_types.lookup_type_alias_params(&alias_file, &matched) {
784	        Some(params) if !args.is_empty() || defaults.is_some() => {
785	            substitute_alias(alias, &bind_args(params, defaults, args, file, &alias_file, &mut Vec::new()))
786	        }
787	        _ => alias.clone(),
788	    };
789	    let body = match alias {
790	        CollectedTypeAlias::Passthrough { target, .. } => target,
791	        CollectedTypeAlias::Intersection { members, .. } => CollectedType::Intersection(members),
792	        CollectedTypeAlias::Union { members, .. } => CollectedType::Union(members),
793	        CollectedTypeAlias::LiteralUnion { members, .. } => {
794	            CollectedType::Union(members.into_iter().map(|m| CollectedType::StringLiteral(m.into())).collect())
795	        }
796	        _ => return None,
797	    };
798	    Some((body, alias_file))
799	}
