43	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
44	            CollectedType::Intersection(members) => pending.extend(members),
45	            CollectedType::Named { name: type_name, args } => {
46	                let key = key(&type_name);
47	                // Defaulted parameters (`T = Element`) are not supplied, and need no warning.
48	                let mut ignored = Vec::new();
49	                if let Some(iface) = ctx.react_index().lookup_interface_exact(react_file, &key) {
50	                    let params = ctx.react_index().lookup_interface_type_params_for(iface);
51	                    let subst = params.map(|params| build_substitution(params, &args, react_file, &mut ignored));
52	                    let substituted =
53	                        |ty: &CollectedType| subst.as_ref().map_or_else(|| ty.clone(), |s| substitute_type(ty, s));
54	                    if let Some(raw) = iface.props.iter().find(|prop| prop.name == name) {
55	                        let ty = substituted(&raw.collected_type);
56	                        let prop_type = resolve_collected_type(&ty, &iface.file_path, ctx, state, depth);
57	                        let parent =
58	                            PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
59	                        return Some(ParsedProp::new(
60	                            name.to_owned(),
61	                            prop_type,
62	                            raw.required,
63	                            None,
64	                            raw.description.clone(),
65	                            raw.tags.clone(),
66	                            Some(parent.clone()),
67	                            vec![parent],
68	                        ));
69	                    }
70	                    pending.extend(iface.extends.iter().map(|extends| {
71	                        let (ExtendsRef::SameFile { name, type_args }
72	                        | ExtendsRef::Imported { local_name: name, type_args, .. }
73	                        | ExtendsRef::Builtin { name, type_args, .. }) = extends;
74	                        CollectedType::Named { name: name.clone(), args: type_args.iter().map(substituted).collect() }
75	                    }));
76	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
77	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
78	                        Some(params) => {
79	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut ignored))
80	                        }
81	                        None => alias.clone(),
82	                    };
83	                    match alias {
84	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
85	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
86	                        _ => {}
87	                    }
88	                }
89	            }
90	            _ => {}
91	        }
92	    }
93	    None
