96	/// Every attribute name `JSX.IntrinsicElements[element]` declares in React's own types at `react_file`, in the order
97	/// `react_attribute` reads them; empty without those types.
98	fn react_attribute_names(element: &str, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
99	    let mut names: Vec<String> = Vec::new();
100	    let Some(root) = intrinsic_element(element, react_file, ctx) else {
101	        return names;
102	    };
103	    let mut pending = VecDeque::from([root.clone()]);
104	    for _ in 0..64 {
105	        let Some(next) = pending.pop_front() else {
106	            break;
107	        };
108	        match next {
109	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
110	            CollectedType::Intersection(members) => pending.extend(members),
111	            CollectedType::Named { name: type_name, args } => {
112	                let key = format!("React.{}", type_name.strip_prefix("React.").unwrap_or(&type_name));
113	                if let Some(iface) = ctx.react_index().lookup_interface_exact(react_file, &key) {
114	                    names.extend(iface.props.iter().map(|prop| prop.name.clone()));
115	                    pending.extend(iface.extends.iter().map(|extends| {
116	                        let (ExtendsRef::SameFile { name, type_args }
117	                        | ExtendsRef::Imported { local_name: name, type_args, .. }
118	                        | ExtendsRef::Builtin { name, type_args, .. }) = extends;
119	                        CollectedType::Named { name: name.clone(), args: type_args.clone() }
120	                    }));
121	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
122	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
123	                        Some(params) => {
124	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut Vec::new()))
125	                        }
126	                        None => alias.clone(),
127	                    };
128	                    match alias {
129	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
130	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
131	                        _ => {}
132	                    }
133	                }
134	            }
135	            _ => {}
136	        }
137	    }
138	    let mut seen = rustc_hash::FxHashSet::default();
139	    names.retain(|name| seen.insert(name.clone()));
140	    names
141	}
