143	/// The attributes of an HTML layer's element that `has` doesn't already list: every one `@types/react` declares when
144	/// `full`, else the curated subset (`react_types::is_curated_html_attr`), each as React declares it minus what the layer
145	/// omits. Without React's types the curated table stands in, typed by name.
146	pub(super) fn layer_attributes(
147	    layer: &InheritedLayer,
148	    full: bool,
149	    has: impl Fn(&str) -> bool,
150	    ctx: &ResolutionContext,
151	    state: &mut ResolveState,
152	    depth: u8,
153	) -> Vec<Arc<ParsedProp>> {
154	    let Some(element) = layer.html_element.as_deref() else {
155	        return Vec::new();
156	    };
157	    let file = Utf8Path::new(&layer.file_name);
158	    // `ref` is a prop of `ComponentProps<"div">` (`ClassAttributes`) but not of `HTMLAttributes<HTMLDivElement>`.
159	    let bare = layer.type_name.strip_prefix("React.").unwrap_or(&layer.type_name);
160	    let takes_ref = matches!(bare, "ComponentProps" | "ComponentPropsWithRef");
161	    let key = format!("{}\0{element}\0{full}", layer.file_name);
162	    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
163	    let names: Arc<[String]> = match cached {
164	        Some(names) => names,
165	        None => {
166	            let declared = react_attribute_names(element, file, ctx);
167	            let names: Vec<String> = match (full, declared.is_empty()) {
168	                (true, false) => declared.into_iter().filter(|name| name != "key").collect(),
169	                (false, false) => declared
170	                    .into_iter()
171	                    .filter(|name| crate::react_types::is_curated_html_attr(element, name))
172	                    .collect(),
173	                (_, true) => Vec::new(),
174	            };
175	            let names: Arc<[String]> = names.into();
176	            ctx.attribute_names.insert(key, names.clone());
177	            names
178	        }
179	    };
180	    let loaded = !names.is_empty();
181	    if full && !loaded {
182	        state.diagnostics.push(
183	            Diagnostic::new(
184	                DiagnosticSeverity::Info,
185	                DiagnosticCode::MissingTypeLibrary,
186	                format!("@types/react could not be resolved, so the attributes of <{element}> are left out"),
187	            )
188	            .with_help("Check that @types/react is installed."),
189	        );
190	        return Vec::new();
191	    }
192	    let names: Vec<String> = if loaded {
193	        names.to_vec()
194	    } else {
195	        crate::react_types::notable_html_attrs(element)
196	            .iter()
197	            .chain(["ref"].iter())
198	            .map(|name| (*name).to_owned())
199	            .collect()
200	    };
201	    let parent = PropParent {
202	        name: format!("{}HTMLAttributes", capitalize_element(element)),
203	        file_name: "node_modules/@types/react/index.d.ts".to_owned(),
204	    };
205	    names
206	        .into_iter()
207	        .filter(|name| (takes_ref || name != "ref") && !has(name) && !layer.omitted.contains(name))
208	        .filter_map(|name| {
209	            if loaded {
210	                return super::alias::layer_attribute(layer, &name, ctx, state, depth).map(|prop| ctx.share(prop));
211	            }
212	            let prop_type = if name == "ref" {
213	                PropType::Named { name: "Ref".into(), args: vec![] }
214	            } else {
215	                infer_html_attr_prop_type(&name)
216	            };
217	            Some(ctx.share(ParsedProp::new(
218	                name,
219	                prop_type,
220	                false,
221	                None,
222	                String::new(),
223	                Default::default(),
224	                Some(parent.clone()),
225	                vec![],
226	            )))
227	        })
228	        .collect()
229	}
