231	pub(super) fn infer_html_attr_prop_type(attr_name: &str) -> PropType {
232	    match attr_name {
233	        "onClick" | "onKeyDown" | "onKeyUp" | "onFocus" | "onBlur" | "onChange" | "onInput" | "onSubmit"
234	        | "onReset" | "onLoad" | "onError" | "onPress" | "onPressStart" | "onPressEnd" | "onHoverStart"
235	        | "onHoverEnd" | "onFocusChange" | "onPressChange" => PropType::Function {
236	            type_params: vec![],
237	            params: vec![FunctionParam::new(Some("e".into()), PropType::Named { name: "Event".into(), args: vec![] })],
238	            return_type: Box::new(PropType::Void),
239	        },
240	        "disabled" | "readOnly" | "required" | "checked" | "multiple" | "noValidate" | "autoFocus" | "fullWidth"
241	        | "loading" | "isDisabled" | "isReadOnly" | "isRequired" => PropType::Boolean,
242	        "tabIndex" | "rows" | "cols" | "maxLength" | "min" | "max" | "width" | "height" | "size" => PropType::Number,
243	        "style" => PropType::CssProperties,
244	        "children" => PropType::ReactNode,
245	        _ => PropType::String,
246	    }
247	}
