249	pub(super) fn capitalize_element(element: &str) -> &'static str {
250	    match element {
251	        "button" => "Button",
252	        "input" => "Input",
253	        "a" => "Anchor",
254	        "textarea" => "Textarea",
255	        "select" => "Select",
256	        "form" => "Form",
257	        "label" => "Label",
258	        "img" => "Img",
259	        "video" => "Video",
260	        "audio" => "Audio",
261	        _ => "HTML",
262	    }
263	}
