869	/// `resolve_component`, with the diagnostics of replayed interface chains shared rather than copied.
870	pub(crate) fn resolve_component_shared(
871	    mapping: &ComponentMapping,
872	    ctx: &ResolutionContext,
873	) -> (ComponentEntry, ResolvedDiagnostics) {
874	    let mut state = ResolveState::default();
875	    state.add_type_params(mapping.type_params.iter());
876	
877	    // A component a generic call builds has the props its callee's result type declares; the props type the extractor
878	    // selected is for a callee whose result isn't known.
879	    let chain = callee::result_chain(mapping, ctx, &mut state).unwrap_or_else(|| {
880	        chain::resolve_props_chain(
881	            mapping.props_type_name.as_str(),
882	            &mapping.props_type_args,
883	            &mapping.file_path,
884	            mapping,
885	            ctx,
886	            &mut state,
887	            0,
888	        )
889	    });
890	
891	    // Build props BTreeMap — own props win over inherited props with same name.
892	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
893	    for prop in chain.props {
894	        props.entry(prop.name.clone()).or_insert(prop);
895	    }
896	    apply_param_defaults(mapping, &mut props, ctx);
897	
898	    // Populate notable_inherited from HTML element layers and non-HTML inherited layers. Curated mode lists the
899	    // curated attributes there; Full mode lists all of them in `props`, except for a layer whose attributes the
900	    // interface chain already merged (`total_props`); None mode lists none.
901	    let mut notable_inherited: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
902	    for layer in &chain.inheritance {
903	        if layer.html_element.is_none() {
904	            continue;
905	        }
906	        match ctx.html_attributes {
907	            crate::pipeline::HtmlAttributeMode::None => {}
908	            crate::pipeline::HtmlAttributeMode::Full => {
909	                if layer.total_props == 0 {
910	                    let added =
911	                        html::layer_attributes(layer, true, |name| props.contains_key(name), ctx, &mut state, 0);
912	                    for prop in added {
913	                        props.entry(prop.name.clone()).or_insert(prop);
914	                    }
915	                }
916	            }
917	            crate::pipeline::HtmlAttributeMode::Curated => {
918	                let added = html::layer_attributes(
919	                    layer,
920	                    false,
921	                    |name| props.contains_key(name) || notable_inherited.contains_key(name),
922	                    ctx,
923	                    &mut state,
924	                    0,
925	                );
926	                for prop in added {
927	                    notable_inherited.entry(prop.name.clone()).or_insert(prop);
928	                }
929	            }
930	        }
931	    }
932	    // A `forwardRef` component takes `ref` whatever its props type declares. The element type isn't recorded, so it is
933	    // `Ref<unknown>` unless the props or an HTML layer gave the real declaration.
934	    let takes_ref = matches!(mapping.rule, DetectionRule::ForwardRef | DetectionRule::ForwardRefExoticDecl);
935	    if takes_ref && ctx.html_attributes != crate::pipeline::HtmlAttributeMode::None {
936	        let target = if ctx.html_attributes == crate::pipeline::HtmlAttributeMode::Full {
937	            &mut props
938	        } else {
939	            &mut notable_inherited
940	        };
941	        if !target.contains_key("ref") {
942	            let ref_type = PropType::Named {
943	                name: "Ref".into(),
944	                args: vec![PropType::Named { name: "unknown".into(), args: vec![] }],
945	            };
946	            // The component takes it, so no interface is its parent, and a consumer that hides React's inherited props
947	            // (the addon's `collapseInheritedProps`) still shows it.
948	            let parent = None;
949	            target.insert(
950	                "ref".to_owned(),
951	                ctx.share(ParsedProp::new(
952	                    "ref".to_owned(),
953	                    ref_type,
954	                    false,
955	                    None,
956	                    String::new(),
957	                    Default::default(),
958	                    parent,
959	                    vec![],
960	                )),
961	            );
962	        }
963	    }
964	    // A collapsed source's notable props (collapse); the only non-HTML layers.
965	    for prop in &chain.notable {
966	        if !props.contains_key(&prop.name) && !notable_inherited.contains_key(&prop.name) {
967	            notable_inherited.insert(prop.name.clone(), prop.clone());
968	        }
969	    }
970	
971	    // Detect discriminated union if applicable.
972	    let discriminant_prop = chain.discriminant_prop;
973	
974	    (
975	        ComponentEntry {
976	            display_name: mapping.component_name.clone(),
977	            file_path: mapping.file_path.clone(),
978	            description: mapping.description.clone(),
979	            props,
980	            inheritance: chain.inheritance,
981	            notable_inherited,
982	            discriminant_prop,
983	            composes: chain.composes,
984	            tags: mapping.tags.clone(),
985	            methods: vec![],
986	            detected_by: mapping.rule,
987	            exported: mapping.exported,
988	        },
989	        ResolvedDiagnostics { own: state.diagnostics, shared: state.shared_diagnostics },
990	    )
991	}
