993	/// A destructuring default is the component's default for that prop wherever the prop's type was declared, as
994	/// TypeScript's docgen reads it. The chain applied it only to props an interface or an object alias declares, so a prop
995	/// that arrives through `Pick<ComponentProps<typeof Button>, "variant">` or another resolved type has none yet.
996	fn apply_param_defaults(
997	    mapping: &ComponentMapping,
998	    props: &mut BTreeMap<String, Arc<ParsedProp>>,
999	    ctx: &ResolutionContext,
1000	) {
1001	    for (name, raw) in &mapping.param_defaults {
1002	        let Some(prop) = props.get_mut(name) else { continue };
1003	        if prop.default_value.is_some() {
1004	            continue;
1005	        }
1006	        let default = DefaultValue { value: raw.value.clone(), computed: raw.computed };
1007	        *prop = ctx.share(prop.with_default_value(default));
1008	    }
1009	}
