1014	/// that inherits them, and into the component, without being copied.
1015	#[derive(Clone)]
1016	pub(crate) struct ResolvedChain {
1017	    /// Resolved props (may include inherited props).
1018	    props: Vec<Arc<ParsedProp>>,
1019	    /// Inheritance layers, outermost first.
1020	    inheritance: Vec<InheritedLayer>,
1021	    /// Inherited props keyed by name — for notable_inherited population.
1022	    inherited_by_name: FxHashMap<String, Arc<ParsedProp>>,
1023	    /// The notable props of collapsed sources, which are not in `props`.
1024	    notable: Vec<Arc<ParsedProp>>,
1025	    /// Type names that could not be resolved.
1026	    composes: Vec<String>,
1027	    /// Discriminant prop name if this is a discriminated union.
