1031	impl ResolvedChain {
1032	    /// The base empty chain. Deliberately not `Default` — every accumulator
1033	    /// site (`resolve_interface_chain`, `resolve_base_as_chain`, ...) that
1034	    /// wants "start empty, then push into" calls this directly instead; the
1035	    /// two *give-up* entry points (`empty_with_compose`, `give_up`) are the
1036	    /// only public-facing "this type contributes nothing" signals. Visible to
1037	    /// `chain`/`alias`/`extends` since they're child modules of `resolver`.
1038	    fn empty() -> Self {
1039	        Self {

30	        // Intersection, and Union targets. Previously this arm only matched
31	        // `Named` and silently dropped everything else (e.g. an inline
32	        // `{ x: string }` object literal used directly as props), which lost
33	        // the whole component's props with no diagnostic.
34	        CollectedTypeAlias::Passthrough { target, file_path } => {
35	            resolve_base_as_chain(target, file_path, mapping, ctx, state, depth)
36	        }
37	
