520	/// attribute's type when React's own declarations are loaded.
521	fn resolve_intersection_chain(
522	    members: &[CollectedType],
523	    file_path: &Utf8Path,
524	    mapping: &ComponentMapping,
525	    ctx: &ResolutionContext,
526	    state: &mut ResolveState,
527	    depth: u8,
528	) -> ResolvedChain {
529	    let mut chain = ResolvedChain::empty();
530	    // HTML layers merged so far whose element's declarations this run has.
531	    let mut layers: Vec<InheritedLayer> = Vec::new();
532	    for member in members {
533	        // Each member is its own branch: a type two members both reach (`Pick<P, K> & Omit<P, K>`, which is Ark's
534	        // `Optional`) is not circular, and the cycle set must hold only the members' ancestors, as for an extends entry.
535	        let mut branch = state.branch();
536	        let mut member = resolve_base_as_chain(member, file_path, mapping, ctx, &mut branch, depth);
537	        state.absorb(branch);
538	        if !layers.is_empty() && !state.keys_only {
539	            let listed: FxHashSet<&str> = chain.props.iter().map(|prop| prop.name.as_str()).collect();
540	            for prop in member.props.iter_mut().filter(|prop| !listed.contains(prop.name.as_str())) {
541	                for layer in &layers {
542	                    if let Some(attribute) = layer_attribute(layer, &prop.name, ctx, state, depth) {
543	                        *prop = ctx.share(super::intersect_declarations(&attribute, prop));
544	                    }
545	                }
546	            }
547	        }
548	        let new_layers: Vec<InheritedLayer> = member
549	            .inheritance
550	            .iter()
551	            .filter(|layer| layer.html_element.as_deref().is_some_and(|element| has_element(layer, element, ctx)))
552	            .cloned()
553	            .collect();
554	        if !new_layers.is_empty() && !state.keys_only {
555	            let own: FxHashSet<&str> = member.props.iter().map(|prop| prop.name.as_str()).collect();
556	            for prop in chain.props.iter_mut().filter(|prop| !own.contains(prop.name.as_str())) {
557	                for layer in &new_layers {
558	                    if let Some(attribute) = layer_attribute(layer, &prop.name, ctx, state, depth) {
559	                        *prop = ctx.share(super::intersect_declarations(prop, &attribute));
560	                    }
561	                }
562	            }
563	        }
564	        layers.extend(new_layers);
565	        chain.intersect_member(member);
566	    }
567	    chain
568	}
