570	/// `ComponentProps<"div">`, when `key_type` is `keyof` it: the type the mapped type ranges over.
571	fn element_props_of(key_type: &CollectedType) -> Option<CollectedType> {
572	    match key_type {
573	        CollectedType::AtFile { inner, .. } => element_props_of(inner),
574	        CollectedType::KeyOf(target) => match target.as_ref() {
575	            CollectedType::AtFile { inner, .. } => element_props_of(&CollectedType::KeyOf(inner.clone())),
576	            CollectedType::Named { name, args } => {
577	                let bare = name.strip_prefix("React.").unwrap_or(name);
578	                let component_props =
579	                    matches!(bare, "ComponentProps" | "ComponentPropsWithRef" | "ComponentPropsWithoutRef");
580	                (component_props && args.len() == 1).then(|| target.as_ref().clone())
581	            }
582	            _ => None,
583	        },
584	        _ => None,
585	    }
586	}
