592	/// The declaration of attribute `name` an HTML layer's element has, unless the layer omits it.
593	pub(super) fn layer_attribute(
594	    layer: &InheritedLayer,
595	    name: &str,
596	    ctx: &ResolutionContext,
597	    state: &mut ResolveState,
598	    depth: u8,
599	) -> Option<ParsedProp> {
600	    if layer.omitted.iter().any(|omitted| omitted == name) {
601	        return None;
602	    }
603	    let element = layer.html_element.as_deref()?;
604	    let key = format!("{}\0{element}\0{name}", layer.file_name);
605	    ctx.attribute_reads.get_or_resolve(&key, depth, state, None, |state| {
606	        super::html::react_attribute(element, name, Utf8Path::new(&layer.file_name), ctx, state, depth)
607	    })
608	}
