use caliper_docgen_core::pipeline::{extract, ComponentAnswer, HtmlAttributeMode, PipelineOptions, WatchSession};
use caliper_docgen_core::types::ExtractionOutput;
use camino::Utf8PathBuf;
use tempfile::TempDir;

const SOURCE: &str = r#"
import * as React from 'react';

export interface AriaPanelProps extends React.AriaAttributes {
    own?: string;
}
export function AriaPanel(props: AriaPanelProps) { return null; }

export type AriaAlias = React.AriaAttributes & { own?: string };
export const AriaAliased = (props: AriaAlias) => null;

export type HtmlBox = Omit<React.HTMLProps<HTMLDivElement>, 'title' | 'aria-label'> & { own?: string };
export const HtmlBoxed = (props: HtmlBox) => null;

export interface InputBox extends React.HTMLProps<HTMLInputElement> {
    own?: string;
}
export function InputBoxed(props: InputBox) { return null; }

export type RefProps = { own?: string } & React.RefAttributes<HTMLButtonElement>;
export const Refed = (props: RefProps) => null;

export type PickedRef = Pick<React.RefAttributes<HTMLButtonElement>, 'ref'> & { own?: string };
export const PickedRefed = (props: PickedRef) => null;
"#;

fn options(dir: &TempDir, mode: HtmlAttributeMode) -> PipelineOptions {
    let root = Utf8PathBuf::from_path_buf(dir.path().to_owned()).unwrap();
    PipelineOptions {
        src_dirs: vec![root.clone()],
        cache_dir: Some(root.join(".cache")),
        html_attributes: mode,
        ..Default::default()
    }
}

/// A project of one file, inside this crate so that `react` resolves to the workspace's `@types/react`.
fn project() -> TempDir {
    let dir = TempDir::new_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    std::fs::write(dir.path().join("Components.tsx"), SOURCE).unwrap();
    dir
}

fn names<'a>(output: &'a ExtractionOutput, component: &str) -> Vec<&'a str> {
    let entry = output.components.get(component).unwrap_or_else(|| panic!("no component {component}"));
    entry.props.keys().map(String::as_str).collect()
}

fn notable<'a>(output: &'a ExtractionOutput, component: &str) -> Vec<&'a str> {
    let entry = output.components.get(component).unwrap_or_else(|| panic!("no component {component}"));
    entry.notable_inherited.keys().map(String::as_str).collect()
}

#[test]
fn probe() {
    let dir = project();
    for mode in [HtmlAttributeMode::Full, HtmlAttributeMode::Curated, HtmlAttributeMode::None] {
        let output = extract(&options(&dir, mode));
        for component in output.components.keys() {
            let props = names(&output, component);
            let notable = notable(&output, component);
            println!("{mode:?} {component}: {} props {:?} / notable {} {:?}", props.len(), props.iter().take(6).collect::<Vec<_>>(), notable.len(), notable.iter().take(6).collect::<Vec<_>>());
        }
        println!("{:?}", output.diagnostics.iter().map(|d| &d.message).collect::<Vec<_>>());
    }
