141	/// `Pick<React.AriaAttributes, 'aria-label'>`: each picked key read from React's interface, as `Pick<T, K>` reads
142	/// `T[K]`, with the optionality and documentation the declaration gives it. Empty when the base is not one of React's
143	/// interfaces. A key React's declaration does not have is reported.
144	#[allow(clippy::too_many_arguments)]
145	fn react_picked_props(
146	    base: &CollectedType,
147	    picked: &[String],
148	    file_path: &Utf8Path,
149	    mapping: &ComponentMapping,
150	    ctx: &ResolutionContext,
151	    state: &mut ResolveState,
152	    depth: u8,
153	) -> Vec<Arc<ParsedProp>> {
154	    let (mut base, mut file) = (base, file_path);
155	    while let CollectedType::AtFile { file: inner_file, inner } = base {
156	        (base, file) = (inner, inner_file.as_path());
157	    }
