    manifests
        .iter()
        .filter(|(_, text)| text.lines().any(|l| l.replace(' ', "").starts_with("panic=\"abort\"")))
        .map(|(path, _)| format!("{path} sets panic = \"abort\"; ADR 0005 needs unwinding"))
        .collect()
}

